322	static const size_t AVAILABLE_NETWORK_VERSIONS_COUNT = sizeof(AVAILABLE_NETWORK_VERSIONS) / sizeof(AVAILABLE_NETWORK_VERSIONS[0]);
323	
324	inline const char* get_latest_network_version() {
325	    for (size_t i = 0; i < AVAILABLE_NETWORK_VERSIONS_COUNT; ++i) {
326	        if (AVAILABLE_NETWORK_VERSIONS[i].is_latest)
327	            return AVAILABLE_NETWORK_VERSIONS[i].version;
328	    }
329	    return AVAILABLE_NETWORK_VERSIONS[0].version;
330	}
