332	struct NetworkLibraryVersionInfo {
333	    std::string version;
334	    std::string base_version;
335	    std::string suffix;
336	    std::string display_name;
337	    std::string url_override;
338	    bool is_latest;
339	    std::string warning;
340	    bool is_discovered;
341	
342	    static NetworkLibraryVersionInfo from_static(const NetworkLibraryVersion& v) {
343	        return {
344	            v.version,
345	            v.version,
346	            "",
347	            v.display_name,
348	            v.url_override ? v.url_override : "",
349	            v.is_latest,
350	            v.warning ? v.warning : "",
351	            false
352	        };
353	    }
354	
355	    static NetworkLibraryVersionInfo from_discovered(const std::string& full_version,
356	                                                      const std::string& base,
357	                                                      const std::string& sfx) {
358	        return {full_version, base, sfx, full_version, "", false, "", true};
359	    }
360	};
361	
362	inline std::string extract_base_version(const std::string& full_version) {
363	    auto pos = full_version.find('-');
364	    return (pos == std::string::npos) ? full_version : full_version.substr(0, pos);
365	}
366	
367	inline std::string extract_suffix(const std::string& full_version) {
368	    auto pos = full_version.find('-');
369	    return (pos == std::string::npos) ? "" : full_version.substr(pos + 1);
370	}
