87	std::shared_ptr<IPrinterAgent> NetworkAgentFactory::create_printer_agent_by_id(const std::string&                  id,
88	                                                                               std::shared_ptr<ICloudServiceAgent> cloud_agent,
89	                                                                               const std::string&                  log_dir)
90	{
91	    std::lock_guard<std::mutex> lock(s_registry_mutex);
92	
93	    // Check cache first
94	    auto& cache    = get_printer_agent_cache();
95	    auto  cache_it = cache.find(id);
96	    if (cache_it != cache.end()) {
97	        BOOST_LOG_TRIVIAL(info) << "Reusing cached printer agent: " << id;
98	        if (cloud_agent)
99	            cache_it->second->set_cloud_agent(cloud_agent);
100	        return cache_it->second;
101	    }
102	
103	    // Not cached — create via factory
104	    auto& agents = get_printer_agents();
105	    auto  it     = agents.find(id);
106	
107	    if (it == agents.end()) {
108	        BOOST_LOG_TRIVIAL(warning) << "Unknown printer agent ID: " << id;
109	        return nullptr;
110	    }
111	
112	    auto agent = it->second.factory(cloud_agent, log_dir);
113	    if (agent) {
114	        BOOST_LOG_TRIVIAL(info) << "Created and cached printer agent: " << id;
115	        cache[id] = agent;
116	    }
117	    return agent;
118	}
