156	std::unique_ptr<NetworkAgent> create_agent_from_config(const std::string& log_dir, AppConfig* app_config)
157	{
158	    if (!app_config)
159	        return std::make_unique<NetworkAgent>(nullptr, nullptr);
160	
161	    // Always create Orca cloud agent as the primary provider
162	    auto cloud_agent = NetworkAgentFactory::create_cloud_agent(ORCA_CLOUD_PROVIDER, log_dir);
163	    if (!cloud_agent) {
164	        BOOST_LOG_TRIVIAL(error) << "Failed to create cloud agent";
165	    }
166	
167	    auto agent = std::make_unique<NetworkAgent>(std::move(cloud_agent), nullptr);
168	
169	    if (agent) {
170	        // create orca cloud agent first
171	        auto* orca_cloud = dynamic_cast<OrcaCloudServiceAgent*>(agent->get_cloud_agent().get());
172	        if (orca_cloud) {
173	            orca_cloud->configure_urls(app_config);
174	        }
175	
176	        // Initialize third-party cloud agents from config
177	        auto providers = app_config->get_cloud_providers();
178	        for (const auto& provider : providers) {
179	            if (provider == ORCA_CLOUD_PROVIDER)
180	                continue; // Primary agent already created above
181	            auto third_party_agent = NetworkAgentFactory::create_cloud_agent(provider, log_dir);
182	            if (third_party_agent) {
183	                agent->add_cloud_agent(provider, std::move(third_party_agent));
184	                BOOST_LOG_TRIVIAL(info) << "Initialized third-party cloud agent: " << provider;
185	            }
186	        }
187	    }
188	
189	    return agent;
190	}
